                FuFirmware *firmware_coswid = g_ptr_array_index(images, i);
                g_autoptr(GBytes) fw = fu_firmware_write(firmware_coswid, error);
                if (fw == NULL)
                        return NULL;
                fu_byte_array_append_bytes(payload, fw);
